export const retryInitialIntervalDefault = 1000
export const retryInitialIntervalMin = 0

export const retryMaxElapsedDefault = 0
export const retryMaxElapsedMin = 0

export const retryMaxIntervalDefault = 60000
export const retryMaxIntervalMin = 0

export const retryMultiplierDefault = 2

export const Retry = zod
	.object({
		initial_interval: zod
			.number()
			.int()
			.min(retryInitialIntervalMin)
			.default(retryInitialIntervalDefault)
			.describe(
				'Milliseconds before the first retry. Omitted or 0 takes the default of 1000.'
			),
		max_elapsed: zod
			.number()
			.int()
			.min(retryMaxElapsedMin)
			.default(retryMaxElapsedDefault)
			.describe(
				'Milliseconds a batch is retried for before it is dropped. 0 (the\ndefault) retries until it lands.'
			),
		max_interval: zod
			.number()
			.int()
			.min(retryMaxIntervalMin)
			.default(retryMaxIntervalDefault)
			.describe(
				'Milliseconds; the longest wait between two retries. Omitted or 0 takes\nthe default of 60000.'
			),
		multiplier: zod
			.number()
			.default(retryMultiplierDefault)
			.describe(
				'Growth of the wait from one retry to the next, at least 1. Omitted or 0\ntakes the default of 2.'
			)
	})
	.describe(
		'How a sink paces the retries of a batch its destination could not take:\n`initial_interval`, growing by `multiplier` up to `max_interval`.'
	)

export type Retry = zod.input<typeof Retry>
export type RetryOutput = zod.output<typeof Retry>

