export const valueOwnedSixBytesItemMin = 0

export type ValueOwned =
	| 'Null'
	| {
			Bool: boolean
	  }
	| {
			Int64: number
	  }
	| {
			Double: number
	  }
	| {
			String: ZStringOwned
	  }
	| {
			/** @items.minimum 0 */
			Bytes: number[]
	  }
	| {
			Array: ValueOwned[]
	  }
	| {
			KvList: KvPair[]
	  }

export const ValueOwned: zod.ZodType<ValueOwned> = zod.union([
	zod.enum(['Null']),
	zod.object({
		Bool: zod.boolean()
	}),
	zod.object({
		Int64: zod.number().int()
	}),
	zod.object({
		Double: zod.number()
	}),
	zod.object({
		String: ZStringOwned
	}),
	zod.object({
		Bytes: zod.array(zod.number().int().min(valueOwnedSixBytesItemMin))
	}),
	zod.object({
		Array: zod.array(zod.lazy(() => ValueOwned))
	}),
	zod.object({
		KvList: zod.array(KvPair)
	})
]) as any

export type ValueOwnedOutput = zod.output<typeof ValueOwned>
